// The real game's effects: the disc's own effect sprites (object-pack parts) driven the way the engine drives them.
//  - play(): an effect script of a pack (object 0x1605, FUN_8008b510 / FUN_8008bb48): keyframed sprites + particle
//    emitters, data in fxScripts.ts (generated by tools/fxscripts.py);
//  - sprite(): one free piece (a part or a flip-book of parts) for effects the game codes by hand.
// Units are PS1 raw (1024 = 1 model unit, y down, angles 4096 per turn, 30 Hz frames); see re/notes/engine.md.
import * as THREE from 'three';
import { ModelInstance, ready } from '../crash';
import { FX_PACKS } from './fxScripts';

/** [frame, x, y, z, rotX, rotY, rotZ, scaleX, scaleY, scaleZ, alpha] */
export type FxKey = number[];
export interface FxEmit {
  x: number; y: number; z: number; pool: number; rate: number; life: number; dur: number; v0: number; v1: number; part: number;
  radius: number; yaw0: number; yaw1: number; pitch0: number; pitch1: number; ax: number; dx: number; ay: number; dy: number;
  az: number; dz: number; fadeIn: number; fadeOut: number; grow: number; shrink: number; spin: number; respawn: number;
}
export interface FxTrack { part?: number; end?: number; keys?: FxKey[]; emit?: FxEmit }
export interface FxScript { dur: number; tracks: FxTrack[] }
export interface FxPack { bill: Record<number, number>; scripts: Record<number, FxScript> }

export interface PlayOpts {
  /** entity scale (1 = 0x1000) */
  scale?: number;
  /** playback rate (1 = the engine's 0x100 per frame) */
  speed?: number;
  /** restart at the end instead of ending (engine mode 0) */
  loop?: boolean;
  /** entity yaw, radians about world y */
  yaw?: number;
  /** start after this many 30 Hz frames */
  delay?: number;
  /** node flag 0x20000000, set by the spawner on every node: draw blended (additive) whatever the mesh's own mode */
  add?: boolean;
  /** follow a moving origin (world position), read every frame */
  at?: () => { x: number; y: number; z: number } | null;
}
export interface SpriteOpts {
  /** seconds */
  life?: number;
  /** world units / s */
  v?: THREE.Vector3;
  /** gravity, world units / s^2 */
  g?: number;
  s0?: number; s1?: number;
  /** in-plane spin, rad / s */
  spin?: number;
  rot?: number;
  /** brightness 1 -> 0 over the life (the engine fades additive sprites by darkening them) */
  fade?: boolean;
  a0?: number;
  /** keep the mesh's own orientation instead of facing the camera */
  flat?: boolean;
  yaw?: number;
  /** trail a moving point: x / z close 1/6 of the gap per tick, y is taken as is (objects 0x1613 / 0x1903) */
  follow?: () => { x: number; y: number; z: number } | null;
  /** node flag 0x20 (objects 0x1306, 0x1709): draw blended (additive) */
  add?: boolean;
  /** frames per second of a flip-book (default: spread over the life) */
  fps?: number;
  loop?: boolean;
}

interface Node { obj: THREE.Object3D; mats: THREE.MeshBasicMaterial[]; bill: boolean; rot: number }
interface Part { n: Node; age: number; x: number; y: number; z: number; vx: number; vy: number; vz: number; s: number; tr: number; live: boolean }
interface Emitter { e: FxEmit; parts: Part[]; ctr: number }
interface Live { script: FxScript; nodes: (Node | null)[]; emit: (Emitter | null)[]; t: number; ticks: number; o: PlayOpts; pos: THREE.Vector3; done: boolean }
/** floating score number (object 0x1409, FUN_8008d2bc): digits are parts 13.. of the HUD pack 0732 */
interface Num { nodes: Node[]; st: number; wait: number; cnt: number; y: number; tgt: number; n: number; c: number; s: number; pos: THREE.Vector3; y0: number; acc: number }
interface Sprite { frames: Node[]; t: number; o: Required<Pick<SpriteOpts, 'life' | 'g' | 's0' | 's1' | 'spin' | 'fade' | 'a0'>> & SpriteOpts; v: THREE.Vector3; rot: number; holder: THREE.Group }

const TAU = Math.PI * 2;
const A = TAU / 4096;
const sx12 = (v: number) => ((v << 20) >> 20); // the engine's 12-bit sign extension of angle differences
const rnd = (n: number) => (n > 0 ? Math.floor(Math.random() * n) : 0); // presentation only (not the sim rng)
const qCam = new THREE.Quaternion(), qZ = new THREE.Quaternion(), eul = new THREE.Euler(), Z = new THREE.Vector3(0, 0, 1), right = new THREE.Vector3();

/** Preload the packs a view plays effects from. */
export const preloadFx = (models: number[]) => ready(models.map((model) => ({ model })));

const templates = new Map<string, THREE.Object3D | null>();
function template(model: number, part: number, scale: number): THREE.Object3D | null {
  const key = `${model}:${part}:${scale}`;
  let t = templates.get(key);
  if (t === undefined) {
    const inst = new ModelInstance({ model, parts: [`part${part}`], scale });
    t = inst.build() ? inst.root : null;
    if (t) {
      const drop: THREE.Object3D[] = [];
      t.traverse((o) => { if ((o as THREE.Mesh).isMesh && !o.visible) drop.push(o); });
      for (const o of drop) o.removeFromParent();
      t.userData.shared = true;
      templates.set(key, t);
    }
  }
  return t ?? null;
}

export class RealFx {
  readonly root = new THREE.Group();
  private live: Live[] = [];
  private sprites: Sprite[] = [];
  private nums: Num[] = [];
  private k: number;

  /** `scale` = the stage's world units per model unit (the scale of the game's props). */
  constructor(parent: THREE.Object3D, private scale: number) {
    this.k = scale / 1024;
    this.root.name = 'realFx';
    this.root.userData.shared = true; // geometry / textures belong to the model cache; own materials are freed in drop()
    parent.add(this.root);
  }

  private node(model: number, part: number, add = false): Node | null {
    const t = template(model, part, this.scale);
    if (!t) return null;
    const obj = new THREE.Group();
    const c = t.clone();
    const mats: THREE.MeshBasicMaterial[] = [];
    c.traverse((m) => {
      const mm = m as THREE.Mesh;
      if (!mm.isMesh) return;
      const own = (q: THREE.Material) => { const n = ownMaterial(q, add); mats.push(n); return n; };
      mm.material = Array.isArray(mm.material) ? mm.material.map(own) : own(mm.material);
      mm.renderOrder = 6;
    });
    obj.add(c);
    obj.visible = false;
    this.root.add(obj);
    return { obj, mats, bill: ((FX_PACKS[model]?.bill[part] ?? 0) & 2) !== 0, rot: 0 };
  }
  private drop(n: Node | null) {
    if (!n) return;
    this.root.remove(n.obj);
    for (const m of n.mats) m.dispose();
  }
  private static shade(n: Node, a: number) { const v = Math.max(0, Math.min(1, a)); for (const m of n.mats) m.color.setScalar(v); }

  /** Play effect script `script` of pack `model` at a world position. */
  play(model: number, script: number, x: number, y: number, z: number, o: PlayOpts = {}): void {
    const s = FX_PACKS[model]?.scripts[script];
    if (!s) return;
    const nodes = s.tracks.map((t) => (t.keys ? this.node(model, t.part!, o.add) : null));
    const emit = s.tracks.map((t) => {
      if (!t.emit) return null;
      const parts: Part[] = [];
      for (let i = 0; i < t.emit.pool; i++) { const n = this.node(model, t.emit.part, o.add); if (n) parts.push({ n, age: 0, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, s: 1, tr: 0, live: false }); }
      return { e: t.emit, parts, ctr: t.emit.rate };
    });
    this.live.push({ script: s, nodes, emit, t: -(o.delay ?? 0), ticks: 0, o, pos: new THREE.Vector3(x, y, z), done: false });
  }

  /** One free piece: a part, or parts flipped through as frames. */
  sprite(model: number, part: number | number[], x: number, y: number, z: number, o: SpriteOpts = {}): void {
    const frames = (Array.isArray(part) ? part : [part]).map((p) => this.node(model, p, o.add)).filter((n): n is Node => !!n);
    if (!frames.length) return;
    const holder = new THREE.Group();
    for (const f of frames) { holder.add(f.obj); f.obj.visible = false; }
    holder.position.set(x, y, z);
    this.root.add(holder);
    this.sprites.push({ frames, t: 0, o: { life: 0.5, g: 0, s0: 1, s1: o.s0 ?? 1, spin: 0, fade: false, a0: 1, ...o }, v: o.v?.clone() ?? new THREE.Vector3(), rot: o.rot ?? 0, holder });
  }

  /**
   * The game's floating score (FUN_8008d5d4 -> object 0x1409): waits `delay` ticks, rises 32 u / tick for 416 u, bobs and grows
   * for 30 ticks, then flies up shrinking for 60. Up to two digits (capped at 99), tens 180 u to the left.
   */
  number(value: number, x: number, y: number, z: number, delay = 0): void {
    let v = Math.max(0, Math.min(99, Math.floor(value)));
    const nodes: Node[] = [];
    do { const n = this.node(732, 13 + (v % 10)); if (n) nodes.push(n); v = Math.floor(v / 10); } while (v > 0);
    if (!nodes.length) return;
    this.nums.push({ nodes, st: 0, wait: delay, cnt: 0, y: 0, tgt: -0x1a0, n: 0, c: 0, s: 0x1000, pos: new THREE.Vector3(x, y, z), y0: y, acc: 0 });
  }
  private numTick(m: Num): boolean {
    if (m.st === 0) { if (m.wait < 1 || --m.wait < 1) m.st = 1; }
    else if (m.st === 1) { m.y -= 0x20; if (m.y <= m.tgt) { m.st = 2; m.cnt = 0x1e; } }
    else if (m.st === 2) {
      m.n++;
      m.y = m.tgt - Math.round(Math.sin(m.n * 0x80 * A) * 96);
      m.s += 0x40;
      if (--m.cnt === 0) { m.st = 3; m.cnt = 0x3c; m.c = 6; }
    } else {
      m.y -= m.c; m.s -= (m.s - 0x800) >> 5; m.c += 3;
      if (--m.cnt === 0) return false;
    }
    return true;
  }

  private place(n: Node, L: Live, x: number, y: number, z: number, rx: number, ry: number, rz: number, sx: number, sy: number, sz: number, a: number) {
    const k = this.k * (L.o.scale ?? 1), yaw = L.o.yaw ?? 0;
    const lx = x * k, lz = -z * k, c = Math.cos(yaw), s = Math.sin(yaw);
    n.obj.position.set(L.pos.x + lx * c + lz * s, L.pos.y - y * k, L.pos.z - lx * s + lz * c);
    const es = L.o.scale ?? 1;
    n.obj.scale.set((sx / 4096) * es, (sy / 4096) * es, (sz / 4096) * es);
    if (n.bill) n.obj.quaternion.copy(qCam).multiply(qZ.setFromAxisAngle(Z, -rz * A));
    else n.obj.quaternion.setFromEuler(eul.set(rx * A, yaw - ry * A, -rz * A, 'YXZ'));
    RealFx.shade(n, a / 4096);
    n.obj.visible = true;
  }

  /** One 30 Hz step of an emitter (FUN_8008ada4: spawn FUN_8001f604, move FUN_8002147c). */
  private tick(em: Emitter) {
    const e = em.e;
    if (em.ctr <= e.pool) {
      let made = 0;
      for (const p of em.parts) {
        if (made >= e.rate) break;
        if (p.live) continue;
        const sp = e.v0 + (e.v1 !== e.v0 ? rnd(Math.abs(e.v1 - e.v0)) : 0);
        const span = (a: number, b: number) => { const d = b < a ? Math.abs(sx12(b - a)) : b - a; return (a + rnd(d)) & 0xfff; };
        const yaw = span(e.yaw0, e.yaw1) * A, pitch = span(e.pitch0, e.pitch1) * A;
        p.vx = sp * Math.sin(yaw); p.vz = sp * Math.cos(yaw); p.vy = -sp * Math.cos(pitch);
        p.x = e.radius * Math.sin(yaw) + e.x; p.z = e.radius * Math.cos(yaw) + e.z; p.y = e.y - e.radius * Math.cos(pitch);
        p.n.rot = e.spin ? rnd(4096) : 0;
        p.tr = e.fadeIn ? 4096 : 0;
        p.s = e.grow ? 0 : 4096;
        p.age = 0; p.live = true;
        made++; em.ctr++;
      }
    }
    for (const p of em.parts) {
      if (!p.live) continue;
      if (e.fadeIn && p.age < e.fadeIn) p.tr = Math.max(0, p.tr - Math.trunc(4096 / e.fadeIn));
      if (e.fadeOut && p.age > e.fadeOut) p.tr = Math.min(4096, p.tr + Math.trunc(4096 / Math.max(1, e.life - e.fadeOut)));
      if (e.grow && p.age <= e.grow) p.s += Math.trunc(4096 / e.grow);
      if (e.shrink && p.age >= e.shrink) p.s = Math.max(0, p.s - (e.life === e.shrink ? 0 : Math.trunc(4096 / (e.life - e.shrink))));
      p.x += p.vx; p.y += p.vy; p.z += p.vz;
      p.vx = ((p.vx * 256 + e.ax) * e.dx) / 65536; p.vy = ((p.vy * 256 + e.ay) * e.dy) / 65536; p.vz = ((p.vz * 256 + e.az) * e.dz) / 65536;
      p.n.rot += e.spin;
      if (p.age++ > e.life) { p.live = false; p.n.obj.visible = false; if (e.respawn) em.ctr = Math.max(0, em.ctr - 1); }
    }
  }

  update(dt: number, camera: THREE.Camera) {
    qCam.copy(camera.quaternion);
    for (let i = this.live.length - 1; i >= 0; i--) {
      const L = this.live[i];
      const at = L.o.at?.();
      if (at) L.pos.set(at.x, at.y, at.z);
      else if (L.o.at && L.o.loop) L.done = true; // a looping effect ends with the thing it rides
      L.t += dt * 30 * (L.o.speed ?? 1);
      if (L.t >= L.script.dur) {
        if (L.o.loop) { L.t %= L.script.dur; L.ticks = 0; for (const em of L.emit) if (em) { em.ctr = em.e.rate; for (const p of em.parts) { p.live = false; p.n.obj.visible = false; } } }
        else L.done = true;
      }
      if (L.done) {
        for (const n of L.nodes) this.drop(n);
        for (const em of L.emit) if (em) for (const p of em.parts) this.drop(p.n);
        this.live.splice(i, 1);
        continue;
      }
      const f = L.t;
      L.script.tracks.forEach((tr, ti) => {
        const n = L.nodes[ti], K = tr.keys;
        if (!n || !K) return;
        if (f < K[0][0] || f > K[K.length - 1][0]) { n.obj.visible = false; return; }
        let j = 0;
        while (j < K.length - 2 && f >= K[j + 1][0]) j++;
        const a = K[j], b = K[j + 1], u = Math.min(1, (f - a[0]) / Math.max(1, b[0] - a[0]));
        const lerp = (q: number) => a[q] + (b[q] - a[q]) * u, ang = (q: number) => a[q] + sx12(b[q] - a[q]) * u;
        this.place(n, L, lerp(1), lerp(2), lerp(3), ang(4), ang(5), ang(6), lerp(7), lerp(8), lerp(9), lerp(10));
      });
      const want = Math.floor(f) + 1;
      while (L.ticks < want) { for (const em of L.emit) if (em) this.tick(em); L.ticks++; }
      const fr = f - Math.floor(f);
      for (const em of L.emit) if (em) for (const p of em.parts) if (p.live) this.place(p.n, L, p.x + p.vx * fr, p.y + p.vy * fr, p.z + p.vz * fr, 0, 0, p.n.rot, p.s, p.s, p.s, 4096 - p.tr);
    }
    for (let i = this.nums.length - 1; i >= 0; i--) {
      const m = this.nums[i];
      m.acc += dt * 30;
      let alive = true;
      while (alive && m.acc >= 1) { m.acc -= 1; alive = this.numTick(m); }
      if (!alive) { for (const n of m.nodes) this.drop(n); this.nums.splice(i, 1); continue; }
      const sc = m.s / 4096;
      right.set(1, 0, 0).applyQuaternion(qCam);
      m.nodes.forEach((n, d) => {
        n.obj.position.copy(m.pos).addScaledVector(right, -0xb4 * d * sc * this.k);
        n.obj.position.y = m.y0 - m.y * this.k;
        n.obj.scale.setScalar(sc);
        n.obj.quaternion.copy(qCam);
        n.obj.visible = true;
      });
    }
    for (let i = this.sprites.length - 1; i >= 0; i--) {
      const s = this.sprites[i], o = s.o;
      s.t += dt;
      if (s.t >= o.life && !o.loop) { for (const f of s.frames) this.drop(f); this.root.remove(s.holder); this.sprites.splice(i, 1); continue; }
      const u = Math.min(1, s.t / o.life);
      s.v.y -= o.g * dt;
      s.holder.position.addScaledVector(s.v, dt);
      const tgt = o.follow?.();
      if (tgt) { const c = 1 - Math.pow(5 / 6, dt * 30), p = s.holder.position; p.set(p.x + (tgt.x - p.x) * c, tgt.y, p.z + (tgt.z - p.z) * c); }
      s.rot += o.spin * dt;
      const n = s.frames.length, fi = o.fps ? Math.floor(s.t * o.fps) : Math.floor(u * n);
      const cur = o.loop ? fi % n : Math.min(n - 1, fi);
      s.frames.forEach((f, j) => {
        f.obj.visible = j === cur;
        if (j !== cur) return;
        f.obj.scale.setScalar(o.s0 + (o.s1 - o.s0) * u);
        if (f.bill && !o.flat) f.obj.quaternion.copy(qCam).multiply(qZ.setFromAxisAngle(Z, s.rot));
        else f.obj.quaternion.setFromEuler(eul.set(0, o.yaw ?? 0, s.rot, 'YXZ'));
        RealFx.shade(f, o.a0 * (o.fade ? 1 - u : 1));
      });
    }
  }

  clear() {
    for (const L of this.live) { for (const n of L.nodes) this.drop(n); for (const em of L.emit) if (em) for (const p of em.parts) this.drop(p.n); }
    for (const s of this.sprites) { for (const f of s.frames) this.drop(f); this.root.remove(s.holder); }
    for (const m of this.nums) for (const n of m.nodes) this.drop(n);
    this.live = []; this.sprites = []; this.nums = [];
  }

  dispose() {
    this.clear();
    this.root.removeFromParent();
  }
}

/** A private copy of a part material that keeps the PS1 shader hooks (clone() drops them); `add` forces additive blending. */
function ownMaterial(q: THREE.Material, add = false): THREE.MeshBasicMaterial {
  const n = q.clone() as THREE.MeshBasicMaterial;
  n.onBeforeCompile = q.onBeforeCompile; n.customProgramCacheKey = q.customProgramCacheKey; n.defines = q.defines;
  n.depthWrite = false;
  if (add) { n.transparent = true; n.blending = THREE.CustomBlending; n.blendEquation = THREE.AddEquation; n.blendSrc = THREE.OneFactor; n.blendDst = THREE.OneFactor; }
  return n;
}

/** Many copies of one pack part (instanced): the game's own mesh for things it spawns in bulk. */
export class PartBatch {
  private meshes: { im: THREE.InstancedMesh; base: THREE.Matrix4 }[] = [];
  private n = 0;
  private m = new THREE.Matrix4(); private q = new THREE.Quaternion(); private p = new THREE.Vector3(); private s = new THREE.Vector3(); private e = new THREE.Euler();
  private own: THREE.Material[] = [];
  constructor(parent: THREE.Object3D, model: number, part: number, scale: number, private max: number, add = false) {
    const t = template(model, part, scale);
    if (!t) return;
    t.updateMatrixWorld(true);
    t.traverse((o) => {
      const mm = o as THREE.Mesh;
      if (!mm.isMesh) return;
      const mk = (q: THREE.Material) => { const n = ownMaterial(q, true); this.own.push(n); return n; };
      const mat = !add ? mm.material : Array.isArray(mm.material) ? mm.material.map(mk) : mk(mm.material);
      const im = new THREE.InstancedMesh(mm.geometry, mat, max);
      if (add) im.renderOrder = 6;
      im.frustumCulled = false; im.count = 0; im.userData.shared = true;
      parent.add(im);
      this.meshes.push({ im, base: mm.matrixWorld.clone() });
    });
  }
  get ok() { return this.meshes.length > 0; }
  begin() { this.n = 0; }
  /** yaw about world y, tilt about the part's own x (radians) */
  add(x: number, y: number, z: number, yaw = 0, tilt = 0, size = 1) {
    if (this.n >= this.max) return;
    this.m.compose(this.p.set(x, y, z), this.q.setFromEuler(this.e.set(tilt, yaw, 0, 'YXZ')), this.s.setScalar(size));
    for (const b of this.meshes) b.im.setMatrixAt(this.n, tmpM.multiplyMatrices(this.m, b.base));
    this.n++;
  }
  end() { for (const b of this.meshes) { b.im.count = this.n; b.im.instanceMatrix.needsUpdate = true; } }
  dispose() { for (const b of this.meshes) { b.im.removeFromParent(); b.im.dispose(); } for (const m of this.own) m.dispose(); this.meshes = []; this.own = []; }
}
const tmpM = new THREE.Matrix4();
